functions.upstream:
export function isComment(line: string) {
  return line.trim().startsWith('#')
}

export function isComment(line: string): boolean {
  return line.trim().startsWith('#');
}

export function isBlank(line: string): boolean {
  return line.trim() === '';
}

export function isComment(rule: string): boolean {
  return rule.trim().startsWith('!');
}

export function isDueDateKeyValue(keyValue: string): boolean {
    return keyValue.startsWith('due:');
}

export function isCommentLine(line: string): boolean {
    return line.trim().startsWith('#');
}

export function isCompletedTask(line: string): boolean {
    return line.trimStart().startsWith('x ');
}

export function isClockLine(line: string): boolean {
    return line.trim().startsWith('CLOCK:');
}

export function isDrawerEnd(line: string): boolean {
    return line.trim() === ':END:';
}

export function isCustomFontId(fontId: string): boolean {
  return fontId.startsWith("custom:");
}

export function isInlineScript(address: string): boolean {
  return address.startsWith('inline-')
}

function doesNotWantTrailingSpace(str: string): boolean {
  return str.endsWith('(');
}

export function getRedisBaseKey(metadataKey: string): string {
  return metadataKey.split(":")[0]
}

export function checkRedisReminderKey(key: string): boolean {
  return key.split(":")[1] === "reminder"
}

export function getCategory(value: string): string {
  return value.split(":")[0];
}

export function extractAppIdFromApiKey(apiKey: string): string {
  return apiKey.split(".")[0] ?? "";
}

export function extractKeyNameFromApiKey(apiKey: string): string {
  return apiKey.split(":")[0] ?? "";
}

function getIconPrefix(iconId: string): string {
  return iconId.split(":")[0];
}

export function getFileName(path: string): string {
  return path.split("/").pop() || path;
}

function parseList(value: string): string[] {
	return value.split(",").map((s) => s.trim());
}

export function parseScopes(raw: string): string[] {
  return raw ? raw.split(",").map((s) => s.trim()).filter(Boolean) : []
}

function getFirstHeaderValue(value: string): string {
  return value.split(",")[0]?.trim() ?? "";
}

export function stripPrefix(value: string, prefix: string): string {
  return value.startsWith(prefix) ? value.slice(prefix.length) : value;
}

export function stripPrefix(path: string, prefix: string): string {
  return path.startsWith(prefix) ? path.slice(prefix.length) : path;
}

export function isAllowedPolicyOff(line: string) {
  return line.includes('eslint-policy-allow-off:');
}

export function isCommentOnlyLine(line: string) {
  return line.trim().startsWith('//');
}

export function addedContent(line: string) {
  return line.slice(1);
}

export function refValueToDefKey(ref: string): string {
  return ref.split("#")[1] || "main";
}

export function stripPrefix(name: string): string {
	return name.split(' ').slice(1).join(' ')
}

export function isBlank(line: string): boolean {
  return line.trim() === '';
}

export function isBlockquote(line: string): boolean {
  return line.trim().startsWith('>');
}

function stripSign(s: string) {
  return s.trim().startsWith('-') ? s.trim().slice(1) : s.trim()
}

export function isSlashCommandInput(line: string): boolean {
  return line.trimStart().startsWith('/')
}
